import re

from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


class BearerStatsFailure(Exception):
    """
    Exception class for bearer_stats
    """
    pass


class BearerStats(EgateCommandBase):
    """
    Parser for bearer_stats command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(BearerStats, self).__init__()
        self.command = 'bearer_stats'
        self.params = params
        self.executed_phrase = r'.*?UE\s\d+.*?EGATE>'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        self.parsers = {
            'dl': self._parse_with_ue_id_and_dir,
            'ul': self._parse_with_ue_id_and_dir,
            'bi': self._parse_with_ue_and_id
        }
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute_and_parse(self, egate_id=0):
        """

        :return:
        """
        status, output = super(BearerStats, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_bearer_stats(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise BearerStatsFailure(output)

    def execute(self, egate_id=0):
        """
        Execute ue_stats_nr command.
        :return: command status and output
        """
        status, output = super(BearerStats, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            return status, output
            logger.debug(output)
        else:
            raise BearerStatsFailure(output)

    def _build_command(self):
        """
        Build bearer_stats command.
        :return: None
        """
        for param, value in self.params.items():
            self.to_execute += ' {}={}'.format(param, value)

    def _parse_bearer_stats(self, output):
        try:
            dir = self.params['dir']
            return self.parsers[dir](output)
        except KeyError:
            return self._parse_with_ue_and_id(output)

    def _parse_with_ue_id_and_dir(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='Parameter', list_of_output_parsed_lines=output)

    def _parse_with_ue_and_id(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        dirs = re.findall(r'(UE\s\d+).*(bearer\s\d+\:\s)(DL|UL).*([\s\S]*?)(?=(UE|EGATE))', cmd_output)
        parsed_dirs_stats = {}

        for dir_stats in dirs:
            current_dir = dir_stats[2]
            cmd_parser = EgateDispCommandsOutputParser(dir_stats[3])
            output = cmd_parser.get_list_of_output_parsed_lines()
            parsed_dirs_stats[current_dir] = create_dict_with_key(key='Parameter', list_of_output_parsed_lines=output)
        return parsed_dirs_stats
